/**
 * Suspending locks a member out without freeing their seat or their role: no
 * `Actor` resolves for them, they vanish from the org switcher, and they can
 * receive no notifications or new work until reinstated. Subject to the same
 * last-owner invariant as removal — suspending the only non-suspended owner
 * is refused.
 */
export async function suspendMember(
  actor: Actor,
  input: SuspendMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot suspend a ${member.role}`);
  }

  if (member.status === "suspended") {
    return member;
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

/**
 * Reverses a suspension: the member regains an `Actor`, reappears in the org
 * switcher, and can be mentioned and assigned work again.
 */
export async function reinstateMember(
  actor: Actor,
  input: ReinstateMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot reinstate a ${member.role}`);
  }

  if (member.status !== "suspended") {
    return member;
  }

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

